/* Signature Madurese Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ahmadnur": "From Ahmad + nur (light): 'praised light'.", "Sitimalay": "From Siti + malay (jasmine, Malay loan).", "Muhammadbahr": "From Muhammad + bahr (sea): 'praised sea'.", "Fatimahcahya": "From Fatimah + cahya (light, Javanese loan).", "Hasankarna": "From Hasan + karna (ear?/deed).", "Zainabsari": "From Zainab + sari (essence/flower).", "Bin Ahmadnur": "Signature patronymic-style surname: 'son of Ahmadnur'.", "Binti Sitimalay": "Signature patronymic-style surname: 'daughter of Sitimalay'.", "Haji Bahruddin": "Signature honorific-style name: 'pilgrim of the sea of faith'.", "Kyai Sari": "Signature title-style name: Kyai (religious teacher) + Sari."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ahmadnur';
console.log(lookup(q));

